ape($item['title']); ?>&quot;? Thao tác này không thể hoàn tác."><?php echo admin_icon('trash'); ?></button></div></td></tr><?php endforeach; ?></tbody></table></div></div><?php endforeach; ?></div></div>
<script>
document.addEventListener('DOMContentLoaded', function () {
	var title = document.querySelector('#entity-modal [name="title"]');
	if (!title || document.querySelector('#entity-modal [name="title_en"]')) return;
	title.parentElement.className = 'col-md-6';
	var field = document.createElement('div');
	field.className = 'col-md-6';
	field.innerHTML = '<label class="form-label" for="home-title-en">Tiêu đề tiếng Anh</label><input class="form-control" id="home-title-en" name="title_en" maxlength="150" placeholder="Để trống sẽ dùng tiêu đề tiếng Việt"><div class="invalid-feedback" data-error-for="title_en"></div>';
	title.parentElement.insertAdjacentElement('afterend', field);
});
</script>
